import re
_P = re.compile(r'(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?')
def parse_duration(text):
    if not isinstance(text, str) or not text:
        raise ValueError(text)
    m = _P.fullmatch(text)
    if not m:
        raise ValueError(text)
    h, mi, s = (int(g) if g else 0 for g in m.groups())
    return h * 3600 + mi * 60 + s

